CREATE OR REPLACE FUNCTION public.finance_installment_page(_today date,_search text DEFAULT '',_filter text DEFAULT 'unpaid',_page integer DEFAULT 0,_size integer DEFAULT 20) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE overview jsonb; selected_rows jsonb; total integer;
BEGIN
 IF _page<0 OR _size NOT IN(10,20,30,40,50) OR length(_search)>120 OR _filter NOT IN('all','unpaid','overdue') THEN RAISE EXCEPTION 'invalid_filter'; END IF;
 overview:=public.finance_dashboard(_today);
 WITH rows AS (SELECT s, r FROM jsonb_array_elements(overview->'schedules') s JOIN jsonb_array_elements(overview->'reservations') r ON r->>'id'=s->>'reservation_id' WHERE (_search='' OR position(lower(_search) IN lower(concat_ws(' ',r->>'guest_name',r->>'company_name',s->>'payment_reference')))>0) AND (_filter='all' OR ((s->>'amount')::numeric>(s->>'paid')::numeric AND CASE WHEN _filter='overdue' THEN (s->>'due_date')::date<_today ELSE substring(s->>'due_date' FROM 1 FOR 7)<=to_char(_today,'YYYY-MM') END))) SELECT count(*) INTO total FROM rows;
 WITH rows AS (SELECT s FROM jsonb_array_elements(overview->'schedules') s JOIN jsonb_array_elements(overview->'reservations') r ON r->>'id'=s->>'reservation_id' WHERE (_search='' OR position(lower(_search) IN lower(concat_ws(' ',r->>'guest_name',r->>'company_name',s->>'payment_reference')))>0) AND (_filter='all' OR ((s->>'amount')::numeric>(s->>'paid')::numeric AND CASE WHEN _filter='overdue' THEN (s->>'due_date')::date<_today ELSE substring(s->>'due_date' FROM 1 FOR 7)<=to_char(_today,'YYYY-MM') END)) ORDER BY s->>'due_date',s->>'id' LIMIT _size OFFSET _page*_size) SELECT coalesce(jsonb_agg(s),'[]') INTO selected_rows FROM rows;
 RETURN jsonb_build_object('total',total,'schedules',selected_rows,'stats',overview->'stats','reservations',coalesce((SELECT jsonb_agg(r) FROM jsonb_array_elements(overview->'reservations') r WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(selected_rows) s WHERE s->>'reservation_id'=r->>'id')),'[]'),'payments',coalesce((SELECT jsonb_agg(p) FROM jsonb_array_elements(overview->'payments') p WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(selected_rows) s WHERE s->>'id'=p->>'schedule_id')),'[]'));
END $$;
CREATE OR REPLACE FUNCTION public.payment_reservation_context(_reservation uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; BEGIN SELECT * INTO r FROM public.reservations WHERE id=_reservation; IF r.id IS NULL OR NOT public.can_finance_action(r.organization_id,r.property_id,'view_finance') THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN jsonb_build_object('schedules',coalesce((SELECT jsonb_agg(to_jsonb(s)||jsonb_build_object('paid',coalesce((SELECT sum(amount) FROM public.payments WHERE schedule_id=s.id AND reversed_at IS NULL),0),'hasPayments',EXISTS(SELECT 1 FROM public.payments WHERE schedule_id=s.id))) FROM public.payment_schedules s WHERE reservation_id=r.id),'[]'),'payments',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM public.payments p WHERE reservation_id=r.id),'[]')); END $$;
CREATE OR REPLACE FUNCTION public.update_guest_contact(_reservation uuid,_email text,_phone text,_company text,_vat text,_address text,_contact text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; BEGIN SELECT * INTO r FROM public.reservations WHERE id=_reservation FOR UPDATE; IF r.id IS NULL OR r.organization_id IS DISTINCT FROM public.active_organization_id() OR NOT public.can_access_property(r.property_id) OR NOT public.has_organization_permission(r.organization_id,'create_reservation') THEN RAISE EXCEPTION 'forbidden'; END IF; IF length(coalesce(_email,''))>254 OR length(coalesce(_phone,''))>80 OR length(coalesce(_company,''))>250 OR length(coalesce(_vat,''))>80 OR length(coalesce(_address,''))>2000 OR length(coalesce(_contact,''))>250 THEN RAISE EXCEPTION 'invalid_contact'; END IF; UPDATE public.reservations SET guest_email=nullif(trim(_email),''),guest_phone=nullif(trim(_phone),''),company_name=nullif(trim(_company),'') WHERE id=r.id; IF r.booking_id IS NOT NULL THEN UPDATE public.bookings SET primary_guest_email=nullif(trim(_email),''),primary_guest_phone=nullif(trim(_phone),''),company_name=nullif(trim(_company),''),company_vat_id=nullif(trim(_vat),''),company_address=nullif(trim(_address),''),company_contact=nullif(trim(_contact),'') WHERE id=r.booking_id AND organization_id=r.organization_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.finance_installment_page(date,text,text,integer,integer),public.payment_reservation_context(uuid),public.update_guest_contact(uuid,text,text,text,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.finance_installment_page(date,text,text,integer,integer),public.payment_reservation_context(uuid),public.update_guest_contact(uuid,text,text,text,text,text,text) TO authenticated;